import{_ as r,o as a,c as t,a2 as n,j as i,a as l}from"./chunks/framework.Buc7gXeZ.js";const m=JSON.parse('{"title":"Häufige Fehlermeldungen","description":"Fehlermeldungen in ApptiveGrid im Wortlaut, mit Ursache und Lösung.","frontmatter":{"title":"Häufige Fehlermeldungen","description":"Fehlermeldungen in ApptiveGrid im Wortlaut, mit Ursache und Lösung."},"headers":[],"relativePath":"fehlerbehebung/haeufige-fehlermeldungen.md","filePath":"fehlerbehebung/haeufige-fehlermeldungen.md","lastUpdated":1786174778000}'),s={name:"fehlerbehebung/haeufige-fehlermeldungen.md"};function h(d,e,o,u,c,g){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="haufige-fehlermeldungen" tabindex="-1">Häufige Fehlermeldungen <a class="header-anchor" href="#haufige-fehlermeldungen" aria-label="Permalink to &quot;Häufige Fehlermeldungen&quot;">​</a></h1><p>Die Meldungen stehen hier <strong>im Wortlaut</strong>, damit Sie danach suchen können.</p><nav class="table-of-contents"><ul><li><a href="#daten-und-eintrage">Daten und Einträge</a><ul><li><a href="#loschen-nicht-moglich-der-eintrag-ist-noch-an-einer-anderen-stelle-referenziert">Löschen nicht möglich. Der Eintrag ist noch an einer anderen Stelle referenziert.</a></li><li><a href="#loschen-nicht-moglich-der-eintrag-wird-noch-von-reference-referenziert">Löschen nicht möglich. Der Eintrag wird noch von {reference} referenziert.</a></li><li><a href="#anderung-nicht-moglich-dieses-feld-wird-in-einem-filter-verwendet">Änderung nicht möglich. Dieses Feld wird in einem Filter verwendet.</a></li><li><a href="#links-auf-grids-die-bereits-an-einer-anderen-stelle-verlinkt-wurden-sind-noch-nicht-moglich">Links auf Grids die bereits an einer anderen Stelle verlinkt wurden, sind noch nicht möglich.</a></li><li><a href="#der-name-existiert-bereits">Der Name existiert bereits</a></li><li><a href="#der-name-kann-maximal-max-zeichen-lang-sein">Der Name kann maximal {max} Zeichen lang sein.</a></li><li><a href="#kein-passender-eintrag-gefunden">Kein passender Eintrag gefunden.</a></li><li><a href="#zeile-gefiltert">Zeile gefiltert</a></li><li><a href="#dieses-grid-wurde-aktualisiert">Dieses Grid wurde aktualisiert</a></li></ul></li><li><a href="#eingaben">Eingaben</a><ul><li><a href="#bitte-fullen-sie-dieses-pflichtfeld-aus">Bitte füllen Sie dieses Pflichtfeld aus.</a></li><li><a href="#es-sind-nur-zahlen-0-9-erlaubt">Es sind nur Zahlen (0-9) erlaubt</a></li><li><a href="#es-sind-nur-gleitkommazahlen-erlaubt">Es sind nur Gleitkommazahlen erlaubt</a></li><li><a href="#gultige-e-mail-adresse-notwendig">Gültige E-Mail-Adresse notwendig</a></li><li><a href="#bitte-geben-sie-eine-gultige-telefonnummer-ein">Bitte geben Sie eine gültige Telefonnummer ein</a></li><li><a href="#internationale-vorwahl-ist-erforderlich-z-b-49">Internationale Vorwahl ist erforderlich (z.B. +49)</a></li><li><a href="#bitte-geben-sie-eine-gultige-url-ein">Bitte geben Sie eine gültige URL ein</a></li><li><a href="#muss-das-format-latitude-longitude-haben-z-b-50-12-6-543">Muss das Format Latitude, Longitude haben (z.B. 50.12,6.543)</a></li><li><a href="#bitte-fullen-sie-die-erforderlichen-unterfelder-aus">Bitte füllen Sie die erforderlichen Unterfelder aus</a></li><li><a href="#unerkanntes-datumsformat">Unerkanntes Datumsformat :</a></li><li><a href="#die-option-darf-nicht-leer-sein-·-die-option-darf-kein-duplikat-sein">Die Option darf nicht leer sein · Die Option darf kein Duplikat sein</a></li></ul></li><li><a href="#filter">Filter</a><ul><li><a href="#alle-vorhandenen-filter-mussen-gultig-sein">Alle vorhandenen Filter müssen gültig sein</a></li><li><a href="#filterbedingungen-konnen-nur-3-ebenen-tief-verschachtelt-werden">Filterbedingungen können nur 3 Ebenen tief verschachtelt werden</a></li></ul></li><li><a href="#zugriff-und-freigaben">Zugriff und Freigaben</a><ul><li><a href="#sie-haben-keinen-zugriff-mehr-auf-diesen-space">Sie haben keinen Zugriff mehr auf diesen Space.</a></li><li><a href="#dieser-space-wurde-geloscht">Dieser Space wurde gelöscht</a></li><li><a href="#nicht-erlaubt">Nicht erlaubt</a></li><li><a href="#zugriff-auf-dieses-formular-ist-eingeschrankt">Zugriff auf dieses Formular ist eingeschränkt.</a></li><li><a href="#diese-ansicht-ist-nicht-mehr-zuganglich">Diese Ansicht ist nicht mehr zugänglich.</a></li><li><a href="#dieser-space-wird-bereits-mit-diesem-benutzer-geteilt">Dieser Space wird bereits mit diesem Benutzer geteilt</a></li><li><a href="#spaces-konnen-nicht-mit-sich-selbst-geteilt-werden">Spaces können nicht mit sich selbst geteilt werden</a></li><li><a href="#benutzer-mit-e-mail-email-existiert-nicht">Benutzer mit E-Mail {email} existiert nicht</a></li><li><a href="#uberschreitung-der-lizenzierten-platze-in-ihrem-tarif">Überschreitung der lizenzierten Plätze in Ihrem Tarif</a></li></ul></li><li><a href="#flows">Flows</a><ul><li><a href="#flow-hat-noch-fehler">Flow hat noch Fehler</a></li><li><a href="#es-wurde-keine-vorherige-ausfuhrung-gefunden">Es wurde keine vorherige Ausführung gefunden.</a></li><li><a href="#fur-diesen-schritt-ist-keine-eigene-ui-hinterlegt-falls-du-eine-ui-benotigst-kannst-du-sie-im-flow-editor-hinzufugen">Für diesen Schritt ist keine eigene UI hinterlegt. Falls du eine UI benötigst, kannst du sie im Flow Editor hinzufügen.</a></li><li><a href="#dieser-prozessschritt-konnte-nicht-geladen-werden">Dieser Prozessschritt konnte nicht geladen werden</a></li><li><a href="#javascript-konnte-nicht-generiert-werden">JavaScript konnte nicht generiert werden</a></li></ul></li><li><a href="#seiten-und-portale">Seiten und Portale</a><ul><li><a href="#diese-ansicht-hat-keine-summierbaren-numerischen-spalten">Diese Ansicht hat keine summierbaren numerischen Spalten</a></li><li><a href="#diese-ansicht-hat-mehr-als-maxrows-zeilen-die-summe-umfasst-nur-die-ersten-maxrows-zeilen">Diese Ansicht hat mehr als {maxRows} Zeilen. Die Summe umfasst nur die ersten {maxRows} Zeilen.</a></li><li><a href="#eingabefelder-ohne-name-oder-id-werden-nicht-in-die-flow-payload-aufgenommen">Eingabefelder ohne name oder id werden nicht in die Flow-Payload aufgenommen.</a></li><li><a href="#count-datei-en-konnten-nicht-hochgeladen-werden">{count} Datei(en) konnten nicht hochgeladen werden</a></li><li><a href="#vorschau-fehler">Vorschau-Fehler</a></li></ul></li><li><a href="#formulare-—-was-ausfullende-sehen">Formulare — was Ausfüllende sehen</a><ul><li><a href="#ups-fehler">Ups - Fehler</a></li><li><a href="#warnung-potenziell-riskantes-formular">Warnung: Potenziell riskantes Formular</a></li><li><a href="#dieses-formular-ist-gesperrt">Dieses Formular ist gesperrt</a></li><li><a href="#geben-sie-nie-ihr-passwort-preis">Geben Sie nie Ihr Passwort preis.</a></li></ul></li><li><a href="#keine-meldung-aber-trotzdem-ein-problem">Keine Meldung, aber trotzdem ein Problem</a></li><li><a href="#weiter">Weiter</a></li></ul></nav><h2 id="daten-und-eintrage" tabindex="-1">Daten und Einträge <a class="header-anchor" href="#daten-und-eintrage" aria-label="Permalink to &quot;Daten und Einträge&quot;">​</a></h2><h3 id="loschen-nicht-moglich-der-eintrag-ist-noch-an-einer-anderen-stelle-referenziert" tabindex="-1">Löschen nicht möglich. Der Eintrag ist noch an einer anderen Stelle referenziert. <a class="header-anchor" href="#loschen-nicht-moglich-der-eintrag-ist-noch-an-einer-anderen-stelle-referenziert" aria-label="Permalink to &quot;Löschen nicht möglich. Der Eintrag ist noch an einer anderen Stelle referenziert.&quot;">​</a></h3><h3 id="loschen-nicht-moglich-der-eintrag-wird-noch-von-reference-referenziert" tabindex="-1">Löschen nicht möglich. Der Eintrag wird noch von {reference} referenziert. <a class="header-anchor" href="#loschen-nicht-moglich-der-eintrag-wird-noch-von-reference-referenziert" aria-label="Permalink to &quot;Löschen nicht möglich. Der Eintrag wird noch von {reference} referenziert.&quot;">​</a></h3><p>Beide Meldungen haben dieselbe Ursache: Der Eintrag ist über eine Verknüpfung mit einem anderen Eintrag verbunden. Die zweite Variante nennt zusätzlich, <strong>welcher</strong> Eintrag darauf verweist — dann können Sie direkt dorthin gehen.</p><p><strong>Lösung:</strong> Lösen Sie zuerst die Verknüpfungen, die auf diesen Eintrag zeigen. Nennt die Meldung den verweisenden Eintrag nicht, hilft eine gefilterte Ansicht im verweisenden Grid, alle betroffenen Einträge zu finden.</p><p>Das ist eine Schutzfunktion — sie verhindert Verweise ins Leere. → <a href="/docs/grids/verknuepfungen">Grids verknüpfen</a></p><h3 id="anderung-nicht-moglich-dieses-feld-wird-in-einem-filter-verwendet" tabindex="-1">Änderung nicht möglich. Dieses Feld wird in einem Filter verwendet. <a class="header-anchor" href="#anderung-nicht-moglich-dieses-feld-wird-in-einem-filter-verwendet" aria-label="Permalink to &quot;Änderung nicht möglich. Dieses Feld wird in einem Filter verwendet.&quot;">​</a></h3><p>Sie wollen den Typ oder Namen eines Feldes ändern, auf das ein Filter zeigt.</p><p><strong>Lösung:</strong> Entfernen Sie den Filter in der betreffenden Ansicht, ändern Sie das Feld, setzen Sie den Filter neu. Der Filter kann in <strong>jeder</strong> Ansicht des Grids liegen, nicht nur in der gerade geöffneten.</p><h3 id="links-auf-grids-die-bereits-an-einer-anderen-stelle-verlinkt-wurden-sind-noch-nicht-moglich" tabindex="-1">Links auf Grids die bereits an einer anderen Stelle verlinkt wurden, sind noch nicht möglich. <a class="header-anchor" href="#links-auf-grids-die-bereits-an-einer-anderen-stelle-verlinkt-wurden-sind-noch-nicht-moglich" aria-label="Permalink to &quot;Links auf Grids die bereits an einer anderen Stelle verlinkt wurden, sind noch nicht möglich.&quot;">​</a></h3><p>Sie versuchen, auf ein Grid zu verweisen, das seinerseits schon anderswo verknüpft ist. Verknüpfungsketten sind nicht möglich.</p><p><strong>Lösung:</strong> Datenmodell flacher gestalten, direkt auf das Zielgrid verweisen oder den Wert über <a href="/docs/grids/berechnete-felder">Wert übernehmen</a> holen. → <a href="/docs/grids/verknuepfungen">Grids verknüpfen</a></p><h3 id="der-name-existiert-bereits" tabindex="-1">Der Name existiert bereits <a class="header-anchor" href="#der-name-existiert-bereits" aria-label="Permalink to &quot;Der Name existiert bereits&quot;">​</a></h3><p>Feld- und Grid-Namen müssen eindeutig sein.</p><h3 id="der-name-kann-maximal-max-zeichen-lang-sein" tabindex="-1">Der Name kann maximal {max} Zeichen lang sein. <a class="header-anchor" href="#der-name-kann-maximal-max-zeichen-lang-sein" aria-label="Permalink to &quot;Der Name kann maximal {max} Zeichen lang sein.&quot;">​</a></h3><p>Kürzen Sie den Namen.</p><h3 id="kein-passender-eintrag-gefunden" tabindex="-1">Kein passender Eintrag gefunden. <a class="header-anchor" href="#kein-passender-eintrag-gefunden" aria-label="Permalink to &quot;Kein passender Eintrag gefunden.&quot;">​</a></h3><p>Im Auswahldialog einer Verknüpfung gibt es keinen Treffer.</p><p><strong>Häufige Ursache:</strong> Die Zielansicht der Verknüpfung ist gefiltert, und der gesuchte Eintrag fällt aus dem Filter. Prüfen Sie den Filter der Zielansicht.</p><h3 id="zeile-gefiltert" tabindex="-1">Zeile gefiltert <a class="header-anchor" href="#zeile-gefiltert" aria-label="Permalink to &quot;Zeile gefiltert&quot;">​</a></h3><p>Kein Fehler, sondern ein Hinweis: Sie haben einen Eintrag so geändert, dass er nicht mehr zum Filter der Ansicht passt, und er wird ausgeblendet.</p><p>Der Eintrag ist <strong>nicht gelöscht</strong>. In einer ungefilterten Ansicht ist er weiterhin da.</p><h3 id="dieses-grid-wurde-aktualisiert" tabindex="-1">Dieses Grid wurde aktualisiert <a class="header-anchor" href="#dieses-grid-wurde-aktualisiert" aria-label="Permalink to &quot;Dieses Grid wurde aktualisiert&quot;">​</a></h3><p>Jemand anderes hat das Grid geändert. Laden Sie die Ansicht neu, um den aktuellen Stand zu sehen.</p><hr><h2 id="eingaben" tabindex="-1">Eingaben <a class="header-anchor" href="#eingaben" aria-label="Permalink to &quot;Eingaben&quot;">​</a></h2><h3 id="bitte-fullen-sie-dieses-pflichtfeld-aus" tabindex="-1">Bitte füllen Sie dieses Pflichtfeld aus. <a class="header-anchor" href="#bitte-fullen-sie-dieses-pflichtfeld-aus" aria-label="Permalink to &quot;Bitte füllen Sie dieses Pflichtfeld aus.&quot;">​</a></h3><p>Ein als Pflichtfeld markiertes Feld ist leer.</p><h3 id="es-sind-nur-zahlen-0-9-erlaubt" tabindex="-1">Es sind nur Zahlen (0-9) erlaubt <a class="header-anchor" href="#es-sind-nur-zahlen-0-9-erlaubt" aria-label="Permalink to &quot;Es sind nur Zahlen (0-9) erlaubt&quot;">​</a></h3><p>Das Feld ist vom Typ <strong>Zahl</strong> und nimmt nur ganze Zahlen. Für Nachkommastellen brauchen Sie <strong>Kommazahl</strong> oder <strong>Währung</strong>.</p><h3 id="es-sind-nur-gleitkommazahlen-erlaubt" tabindex="-1">Es sind nur Gleitkommazahlen erlaubt <a class="header-anchor" href="#es-sind-nur-gleitkommazahlen-erlaubt" aria-label="Permalink to &quot;Es sind nur Gleitkommazahlen erlaubt&quot;">​</a></h3><p>Der Wert passt nicht zum Typ <strong>Kommazahl</strong>. Achten Sie auf das Dezimaltrennzeichen.</p><h3 id="gultige-e-mail-adresse-notwendig" tabindex="-1">Gültige E-Mail-Adresse notwendig <a class="header-anchor" href="#gultige-e-mail-adresse-notwendig" aria-label="Permalink to &quot;Gültige E-Mail-Adresse notwendig&quot;">​</a></h3><p>Die Eingabe ist keine gültige E-Mail-Adresse.</p><h3 id="bitte-geben-sie-eine-gultige-telefonnummer-ein" tabindex="-1">Bitte geben Sie eine gültige Telefonnummer ein <a class="header-anchor" href="#bitte-geben-sie-eine-gultige-telefonnummer-ein" aria-label="Permalink to &quot;Bitte geben Sie eine gültige Telefonnummer ein&quot;">​</a></h3><h3 id="internationale-vorwahl-ist-erforderlich-z-b-49" tabindex="-1">Internationale Vorwahl ist erforderlich (z.B. +49) <a class="header-anchor" href="#internationale-vorwahl-ist-erforderlich-z-b-49" aria-label="Permalink to &quot;Internationale Vorwahl ist erforderlich (z.B. +49)&quot;">​</a></h3><p>Telefonnummern brauchen eine Ländervorwahl.</p><p><strong>Tipp für Formularersteller:</strong> Weisen Sie in der Feldbeschreibung darauf hin, sonst häufen sich Fehleingaben.</p><h3 id="bitte-geben-sie-eine-gultige-url-ein" tabindex="-1">Bitte geben Sie eine gültige URL ein <a class="header-anchor" href="#bitte-geben-sie-eine-gultige-url-ein" aria-label="Permalink to &quot;Bitte geben Sie eine gültige URL ein&quot;">​</a></h3><p>Vollständige Adresse inklusive <code>https://</code> eingeben.</p><h3 id="muss-das-format-latitude-longitude-haben-z-b-50-12-6-543" tabindex="-1">Muss das Format Latitude, Longitude haben (z.B. 50.12,6.543) <a class="header-anchor" href="#muss-das-format-latitude-longitude-haben-z-b-50-12-6-543" aria-label="Permalink to &quot;Muss das Format Latitude, Longitude haben (z.B. 50.12,6.543)&quot;">​</a></h3><p>Geokoordinaten als zwei durch Komma getrennte Zahlen, Dezimaltrennzeichen ist der Punkt.</p><h3 id="bitte-fullen-sie-die-erforderlichen-unterfelder-aus" tabindex="-1">Bitte füllen Sie die erforderlichen Unterfelder aus <a class="header-anchor" href="#bitte-fullen-sie-die-erforderlichen-unterfelder-aus" aria-label="Permalink to &quot;Bitte füllen Sie die erforderlichen Unterfelder aus&quot;">​</a></h3><p>Ein Adressfeld ist unvollständig.</p>',47),i("h3",{date:"",id:"unerkanntes-datumsformat",tabindex:"-1"},[l("Unerkanntes Datumsformat : "),i("a",{class:"header-anchor",href:"#unerkanntes-datumsformat","aria-label":'Permalink to "Unerkanntes Datumsformat : {date}"'},"​")],-1),n('<p>Das eingegebene oder importierte Datum ist nicht lesbar. Tritt häufig beim <a href="/docs/grids/csv-import">CSV-Import</a> auf.</p><h3 id="die-option-darf-nicht-leer-sein-·-die-option-darf-kein-duplikat-sein" tabindex="-1">Die Option darf nicht leer sein · Die Option darf kein Duplikat sein <a class="header-anchor" href="#die-option-darf-nicht-leer-sein-·-die-option-darf-kein-duplikat-sein" aria-label="Permalink to &quot;Die Option darf nicht leer sein · Die Option darf kein Duplikat sein&quot;">​</a></h3><p>Betrifft die Optionsliste von <strong>Einzelauswahl</strong> und <strong>Mehrfachauswahl</strong>.</p><hr><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><h3 id="alle-vorhandenen-filter-mussen-gultig-sein" tabindex="-1">Alle vorhandenen Filter müssen gültig sein <a class="header-anchor" href="#alle-vorhandenen-filter-mussen-gultig-sein" aria-label="Permalink to &quot;Alle vorhandenen Filter müssen gültig sein&quot;">​</a></h3><p>Eine Filterbedingung ist unvollständig. Vervollständigen oder entfernen Sie sie — bis dahin wirkt der Filter nicht.</p><h3 id="filterbedingungen-konnen-nur-3-ebenen-tief-verschachtelt-werden" tabindex="-1">Filterbedingungen können nur 3 Ebenen tief verschachtelt werden <a class="header-anchor" href="#filterbedingungen-konnen-nur-3-ebenen-tief-verschachtelt-werden" aria-label="Permalink to &quot;Filterbedingungen können nur 3 Ebenen tief verschachtelt werden&quot;">​</a></h3><p>Sie haben die maximale Verschachtelung erreicht.</p><p><strong>Lösung:</strong> Legen Sie ein Hilfsfeld vom Typ <strong>Formel</strong> oder <strong>Häkchen</strong> an, das die komplexe Bedingung abbildet, und filtern Sie darauf. → <a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><hr><h2 id="zugriff-und-freigaben" tabindex="-1">Zugriff und Freigaben <a class="header-anchor" href="#zugriff-und-freigaben" aria-label="Permalink to &quot;Zugriff und Freigaben&quot;">​</a></h2><h3 id="sie-haben-keinen-zugriff-mehr-auf-diesen-space" tabindex="-1">Sie haben keinen Zugriff mehr auf diesen Space. <a class="header-anchor" href="#sie-haben-keinen-zugriff-mehr-auf-diesen-space" aria-label="Permalink to &quot;Sie haben keinen Zugriff mehr auf diesen Space.&quot;">​</a></h3><p>Ihre Berechtigung wurde entzogen. Wenden Sie sich an den Eigentümer des Space.</p><h3 id="dieser-space-wurde-geloscht" tabindex="-1">Dieser Space wurde gelöscht <a class="header-anchor" href="#dieser-space-wurde-geloscht" aria-label="Permalink to &quot;Dieser Space wurde gelöscht&quot;">​</a></h3><h3 id="nicht-erlaubt" tabindex="-1">Nicht erlaubt <a class="header-anchor" href="#nicht-erlaubt" aria-label="Permalink to &quot;Nicht erlaubt&quot;">​</a></h3><p>Ihre <a href="/docs/zusammenarbeit/rollen">Rolle</a> erlaubt diese Aktion nicht.</p><h3 id="zugriff-auf-dieses-formular-ist-eingeschrankt" tabindex="-1">Zugriff auf dieses Formular ist eingeschränkt. <a class="header-anchor" href="#zugriff-auf-dieses-formular-ist-eingeschrankt" aria-label="Permalink to &quot;Zugriff auf dieses Formular ist eingeschränkt.&quot;">​</a></h3><p>Für den Formularlink gilt eine Zugriffsbeschränkung, die Sie nicht erfüllen — etwa <em>Jeder registrierte Benutzer</em> oder <em>Jeder aus diesem Space</em>.</p><p><strong>Lösung:</strong> Anmelden, oder den Formularersteller um Zugriff bitten. → <a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></p><h3 id="diese-ansicht-ist-nicht-mehr-zuganglich" tabindex="-1">Diese Ansicht ist nicht mehr zugänglich. <a class="header-anchor" href="#diese-ansicht-ist-nicht-mehr-zuganglich" aria-label="Permalink to &quot;Diese Ansicht ist nicht mehr zugänglich.&quot;">​</a></h3><p>Die geteilte Ansicht wurde gelöscht oder die Freigabe entfernt.</p><h3 id="dieser-space-wird-bereits-mit-diesem-benutzer-geteilt" tabindex="-1">Dieser Space wird bereits mit diesem Benutzer geteilt <a class="header-anchor" href="#dieser-space-wird-bereits-mit-diesem-benutzer-geteilt" aria-label="Permalink to &quot;Dieser Space wird bereits mit diesem Benutzer geteilt&quot;">​</a></h3><p>Die Person hat schon Zugriff. Ändern Sie stattdessen ihre Rolle in der Liste <em>Geteilt mit</em>.</p><h3 id="spaces-konnen-nicht-mit-sich-selbst-geteilt-werden" tabindex="-1">Spaces können nicht mit sich selbst geteilt werden <a class="header-anchor" href="#spaces-konnen-nicht-mit-sich-selbst-geteilt-werden" aria-label="Permalink to &quot;Spaces können nicht mit sich selbst geteilt werden&quot;">​</a></h3><p>Sie haben Ihre eigene Adresse eingegeben.</p><h3 id="benutzer-mit-e-mail-email-existiert-nicht" tabindex="-1">Benutzer mit E-Mail {email} existiert nicht <a class="header-anchor" href="#benutzer-mit-e-mail-email-existiert-nicht" aria-label="Permalink to &quot;Benutzer mit E-Mail {email} existiert nicht&quot;">​</a></h3><p>Zu dieser Adresse gibt es kein ApptiveGrid-Konto. Schreibweise prüfen; ansonsten muss sich die Person zuerst registrieren.</p><h3 id="uberschreitung-der-lizenzierten-platze-in-ihrem-tarif" tabindex="-1">Überschreitung der lizenzierten Plätze in Ihrem Tarif <a class="header-anchor" href="#uberschreitung-der-lizenzierten-platze-in-ihrem-tarif" aria-label="Permalink to &quot;Überschreitung der lizenzierten Plätze in Ihrem Tarif&quot;">​</a></h3><p>Sie haben mehr Personen mit Bearbeitungsrechten eingeladen, als Plätze vorhanden sind.</p><p><strong>Lösung:</strong> Rollen auf <em>Ansehen</em> herabstufen — das ist kostenfrei — oder Plätze nachbuchen. → <a href="/docs/zusammenarbeit/sitzplaetze">Sitzplätze</a></p><hr><h2 id="flows" tabindex="-1">Flows <a class="header-anchor" href="#flows" aria-label="Permalink to &quot;Flows&quot;">​</a></h2><h3 id="flow-hat-noch-fehler" tabindex="-1">Flow hat noch Fehler <a class="header-anchor" href="#flow-hat-noch-fehler" aria-label="Permalink to &quot;Flow hat noch Fehler&quot;">​</a></h3><p>Ein Schritt ist unvollständig konfiguriert. Gehen Sie die Schritte durch; der betroffene ist im Editor markiert.</p><h3 id="es-wurde-keine-vorherige-ausfuhrung-gefunden" tabindex="-1">Es wurde keine vorherige Ausführung gefunden. <a class="header-anchor" href="#es-wurde-keine-vorherige-ausfuhrung-gefunden" aria-label="Permalink to &quot;Es wurde keine vorherige Ausführung gefunden.&quot;">​</a></h3><p>Sie wollen einen Flow mit den Daten des letzten Durchlaufs starten, es gab aber noch keinen.</p><p><strong>Lösung:</strong> Erst einmal regulär testen. → <a href="/docs/flows/testen">Flows testen</a></p><h3 id="fur-diesen-schritt-ist-keine-eigene-ui-hinterlegt-falls-du-eine-ui-benotigst-kannst-du-sie-im-flow-editor-hinzufugen" tabindex="-1">Für diesen Schritt ist keine eigene UI hinterlegt. Falls du eine UI benötigst, kannst du sie im Flow Editor hinzufügen. <a class="header-anchor" href="#fur-diesen-schritt-ist-keine-eigene-ui-hinterlegt-falls-du-eine-ui-benotigst-kannst-du-sie-im-flow-editor-hinzufugen" aria-label="Permalink to &quot;Für diesen Schritt ist keine eigene UI hinterlegt. Falls du eine UI benötigst, kannst du sie im Flow Editor hinzufügen.&quot;">​</a></h3><p>Ein Flow-Schritt soll eine Seite anzeigen, es ist aber keine zugewiesen.</p><p><strong>Häufige Ursache:</strong> Die zugewiesene Seite wurde gelöscht. Prüfen Sie am Schritt <em>Seite anzeigen</em>, welche Seite hinterlegt ist.</p><h3 id="dieser-prozessschritt-konnte-nicht-geladen-werden" tabindex="-1">Dieser Prozessschritt konnte nicht geladen werden <a class="header-anchor" href="#dieser-prozessschritt-konnte-nicht-geladen-werden" aria-label="Permalink to &quot;Dieser Prozessschritt konnte nicht geladen werden&quot;">​</a></h3><p>Mit dem Zusatz:</p><blockquote><p><em>Der aktuelle Schritt konnte aufgrund einer fehlerhaften Konfiguration oder eines ungültigen Werts nicht ausgeführt werden.</em></p><p><em>Bitte wenden Sie sich an den Verantwortlichen für diesen Prozess oder den Administrator Ihrer Organisation.</em></p></blockquote><p>Diese Meldung sehen <strong>Endanwender</strong>. Als Verantwortlicher prüfen Sie die <a href="/docs/flows/durchlaufhistorie">Durchlaufhistorie</a> — dort steht über <em>Fehlerdetails anzeigen</em>, welcher Schritt gescheitert ist.</p><h3 id="javascript-konnte-nicht-generiert-werden" tabindex="-1">JavaScript konnte nicht generiert werden <a class="header-anchor" href="#javascript-konnte-nicht-generiert-werden" aria-label="Permalink to &quot;JavaScript konnte nicht generiert werden&quot;">​</a></h3><p>Die KI-Erzeugung im JavaScript-Schritt ist fehlgeschlagen. Beschreibung präzisieren und erneut versuchen.</p><hr><h2 id="seiten-und-portale" tabindex="-1">Seiten und Portale <a class="header-anchor" href="#seiten-und-portale" aria-label="Permalink to &quot;Seiten und Portale&quot;">​</a></h2><h3 id="diese-ansicht-hat-keine-summierbaren-numerischen-spalten" tabindex="-1">Diese Ansicht hat keine summierbaren numerischen Spalten <a class="header-anchor" href="#diese-ansicht-hat-keine-summierbaren-numerischen-spalten" aria-label="Permalink to &quot;Diese Ansicht hat keine summierbaren numerischen Spalten&quot;">​</a></h3><p>Die Summenkarte braucht eine Spalte vom Typ <strong>Zahl</strong>, <strong>Kommazahl</strong> oder <strong>Währung</strong> in der eingebetteten Ansicht.</p><p><strong>Häufige Ursache:</strong> Die Spalte existiert, ist in dieser Ansicht aber ausgeblendet.</p><h3 id="diese-ansicht-hat-mehr-als-maxrows-zeilen-die-summe-umfasst-nur-die-ersten-maxrows-zeilen" tabindex="-1">Diese Ansicht hat mehr als {maxRows} Zeilen. Die Summe umfasst nur die ersten {maxRows} Zeilen. <a class="header-anchor" href="#diese-ansicht-hat-mehr-als-maxrows-zeilen-die-summe-umfasst-nur-die-ersten-maxrows-zeilen" aria-label="Permalink to &quot;Diese Ansicht hat mehr als {maxRows} Zeilen. Die Summe umfasst nur die ersten {maxRows} Zeilen.&quot;">​</a></h3><p>Kein Fehler, aber wichtig: Die angezeigte Summe ist <strong>unvollständig</strong>.</p><p><strong>Lösung:</strong> Für belastbare Gesamtsummen eine <a href="/docs/ansichten/filtern-sortieren-gruppieren">Gruppierung mit Aggregat</a> oder ein Feld vom Typ <a href="/docs/grids/berechnete-felder">Summe berechnen</a> verwenden.</p><h3 id="eingabefelder-ohne-name-oder-id-werden-nicht-in-die-flow-payload-aufgenommen" tabindex="-1">Eingabefelder ohne name oder id werden nicht in die Flow-Payload aufgenommen. <a class="header-anchor" href="#eingabefelder-ohne-name-oder-id-werden-nicht-in-die-flow-payload-aufgenommen" aria-label="Permalink to &quot;Eingabefelder ohne name oder id werden nicht in die Flow-Payload aufgenommen.&quot;">​</a></h3><p>Betrifft den Block <em>HTML mit Formularfeldern</em>. Ohne <code>name</code>- oder <code>id</code>-Attribut geht der Wert verloren.</p><h3 id="count-datei-en-konnten-nicht-hochgeladen-werden" tabindex="-1">{count} Datei(en) konnten nicht hochgeladen werden <a class="header-anchor" href="#count-datei-en-konnten-nicht-hochgeladen-werden" aria-label="Permalink to &quot;{count} Datei(en) konnten nicht hochgeladen werden&quot;">​</a></h3><p>Häufigste Ursache ist die tarifabhängige Größenbeschränkung.</p><h3 id="vorschau-fehler" tabindex="-1">Vorschau-Fehler <a class="header-anchor" href="#vorschau-fehler" aria-label="Permalink to &quot;Vorschau-Fehler&quot;">​</a></h3><p>Der HTML-Block enthält fehlerhaften Code.</p><hr><h2 id="formulare-—-was-ausfullende-sehen" tabindex="-1">Formulare — was Ausfüllende sehen <a class="header-anchor" href="#formulare-—-was-ausfullende-sehen" aria-label="Permalink to &quot;Formulare — was Ausfüllende sehen&quot;">​</a></h2><h3 id="ups-fehler" tabindex="-1">Ups - Fehler <a class="header-anchor" href="#ups-fehler" aria-label="Permalink to &quot;Ups - Fehler&quot;">​</a></h3><p>Allgemeine Fehlermeldung beim Absenden.</p><h3 id="warnung-potenziell-riskantes-formular" tabindex="-1">Warnung: Potenziell riskantes Formular <a class="header-anchor" href="#warnung-potenziell-riskantes-formular" aria-label="Permalink to &quot;Warnung: Potenziell riskantes Formular&quot;">​</a></h3><p>Das Formular wurde als möglicherweise missbräuchlich eingestuft. Über <em>Dennoch öffnen</em> gelangen Sie weiter.</p><p><strong>Als Formularersteller:</strong> Wenden Sie sich an <code>abuse@apptivegrid.com</code>, um eine Überprüfung zu beantragen.</p><h3 id="dieses-formular-ist-gesperrt" tabindex="-1">Dieses Formular ist gesperrt <a class="header-anchor" href="#dieses-formular-ist-gesperrt" aria-label="Permalink to &quot;Dieses Formular ist gesperrt&quot;">​</a></h3><p>Das Formular wurde gesperrt. Kontakt ebenfalls <code>abuse@apptivegrid.com</code>.</p><h3 id="geben-sie-nie-ihr-passwort-preis" tabindex="-1">Geben Sie nie Ihr Passwort preis. <a class="header-anchor" href="#geben-sie-nie-ihr-passwort-preis" aria-label="Permalink to &quot;Geben Sie nie Ihr Passwort preis.&quot;">​</a></h3><p>Kein Fehler, sondern ein Sicherheitshinweis auf jedem Formular. Geben Sie in Formularen niemals Passwörter oder Zugangsdaten ein.</p><hr><h2 id="keine-meldung-aber-trotzdem-ein-problem" tabindex="-1">Keine Meldung, aber trotzdem ein Problem <a class="header-anchor" href="#keine-meldung-aber-trotzdem-ein-problem" aria-label="Permalink to &quot;Keine Meldung, aber trotzdem ein Problem&quot;">​</a></h2><p>Manches erscheint ohne Fehlermeldung:</p><table tabindex="0"><thead><tr><th>Beobachtung</th><th>Ursache</th></tr></thead><tbody><tr><td>Eine Schaltfläche fehlt</td><td>Fehlende Berechtigung → <a href="/docs/fehlerbehebung/fehlende-schaltflaechen">Ich sehe eine Schaltfläche nicht</a></td></tr><tr><td>Ein Flow startet nicht</td><td>Auslöser zeigt auf ein anderes Grid oder Formular</td></tr><tr><td>Ein Flow startet endlos</td><td>Eine Aktion schreibt in das Grid, das ihn auslöst</td></tr><tr><td>Ein Eintrag ist verschwunden</td><td>Er fällt aus dem Filter der Ansicht</td></tr><tr><td>Ein Feld fehlt im Formular</td><td>Der Spaltentyp hat kein Formularfeld, etwa <em>Formatierter Text</em></td></tr><tr><td>Ein Portal zeigt zu viele Daten</td><td>Die eingebettete Ansicht ist nicht ausreichend gefiltert</td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/fehlerbehebung/fehlende-schaltflaechen">Ich sehe eine Schaltfläche nicht</a></li><li><a href="/docs/zusammenarbeit/rollen">Rollen</a></li><li><a href="/docs/referenz/glossar">Glossar</a></li></ul>',78)])])}const b=r(s,[["render",h]]);export{m as __pageData,b as default};
